from pathlib import Path
import re
root=Path(__file__).parent
old=(root/'question-bank-options-1.html').read_text(encoding='utf-8')
css=re.search(r'<style>(.*?)</style>',old,re.S).group(1)
brand=re.search(r'<div class="app-brand">.*?</div>',old,re.S).group(0)
nav=re.search(r'<nav>.*?</nav>',old,re.S).group(0)
css+='''
.gallery{grid-template-columns:repeat(2,minmax(0,1fr));gap:26px;max-width:840px;margin:auto}.phone{height:790px;padding:22px 20px 90px}.phone h1{margin-bottom:6px}.subtitle{color:#9792a7;font-size:12px;margin:0 0 23px}.headrow{display:flex;align-items:center;justify-content:space-between}.headrow button{width:42px;height:42px;border-radius:13px;font-size:24px;background:#8a6bff;color:white;border:0}.tools{display:flex;align-items:center;gap:10px;margin:20px 0;font-size:12px;color:#aaa4bc}.tools .find{flex:1;background:#252630;padding:13px;border-radius:10px}.tools button{min-height:40px}.section-label{font-size:10px;letter-spacing:.12em;color:#9b91b0;padding:14px 0 12px;border-bottom:1px solid #48404f}.note{display:grid;grid-template-columns:25px 1fr 20px;gap:10px;padding:21px 0;border-bottom:1px solid #39333f}.note .num{font-size:11px;color:#84759b;padding-top:3px}.note b{font-size:15px;line-height:1.5;font-weight:500}.note small{display:block;color:#968b9f;font-size:10px;margin-top:9px}.note .arrow{color:#ac90ff;font-size:20px}.subtools{display:flex;justify-content:space-between;font-size:11px;color:#a58bcc;margin-top:23px}.expand{padding:19px 0;border-bottom:1px solid #3d3747;font-size:14px;line-height:1.5}.expand-head{display:flex;gap:13px;align-items:center}.expand-head span{flex:1}.expanded{background:#282334;border-radius:13px;padding:17px;margin-top:15px}.expanded small{color:#a48fbf;font-size:10px}.expanded p{font-size:15px;color:#eee5ff;margin:12px 0 16px}.expanded button{background:#8b6aff;color:#fff;border:0;width:100%;font-size:12px}.inline-meta{font-size:10px;color:#a493b7;margin-top:9px}.deck{margin-top:24px;position:relative}.deck:before,.deck:after{content:'';position:absolute;top:12px;left:10px;right:10px;height:300px;border:1px solid #514264;background:#25222e;border-radius:22px;transform:rotate(3deg)}.deck:after{transform:rotate(-3deg)}.paper{position:relative;z-index:1;border:1px solid #705994;background:linear-gradient(140deg,#352744,#232430);border-radius:22px;padding:26px 22px;min-height:310px}.paper .deck-label{display:flex;justify-content:space-between;color:#bca4db;font-size:11px}.paper h2{font-size:25px;line-height:1.45;margin:36px 0 24px}.paper .answer{color:#c6b0e5;font-size:12px;border-top:1px solid #5a466b;padding-top:17px}.deck-controls{display:flex;align-items:center;justify-content:space-between;margin-top:26px;color:#b0a5be;font-size:12px}.deck-controls button{width:44px;border-radius:50%;font-size:20px}.deck-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:20px}.deck-actions button{font-size:12px;min-height:44px}.shelf{display:flex;align-items:center;padding:18px 0;border-bottom:1px solid #3b3544;gap:15px}.shelf .book{width:45px;height:56px;border-radius:3px 8px 8px 3px;background:#372b4f;border-left:5px solid #9671d7;display:grid;place-items:center;font-size:21px;color:#c2a5ec}.shelf:nth-child(2) .book{background:#243f3b;border-color:#67afa3;color:#91d6c8}.shelf:nth-child(3) .book{background:#443424;border-color:#cca367;color:#e4c18e}.shelf div{flex:1}.shelf b{display:block;font-size:16px;margin-bottom:8px}.shelf small{font-size:11px;color:#a398ad}.directory-detail{margin:20px 0;padding:16px;background:#25222d;border-radius:12px}.directory-detail b{font-size:12px;color:#c1a8e0}.directory-detail p{font-size:13px;line-height:1.7;color:#e6dfef;margin:13px 0 4px}.directory-detail small{font-size:10px;color:#94899e}@media(max-width:760px){.gallery{grid-template-columns:1fr;max-width:390px}}
'''
header='<div class="headrow"><div><h1>Questions</h1><p class="subtitle">17 questions in your library</p></div><button>＋</button></div>'
tools='<div class="tools"><div class="find">⌕ &nbsp; Search questions</div><button>☷</button><button>⋯</button></div>'
contents=[
('A · Notebook',header+tools+'<div class="section-label">YOUR QUESTIONS · NEWEST FIRST</div>'+''.join(f'<div class="note"><span class="num">0{i}</span><div><b>{q}</b><small>{t}</small></div><span class="arrow">↗</span></div>' for i,q,t in [(1,'What is the capital of Japan?','Multiple choice · Geography'),(2,'Match each country to its capital.','Matching · Geography'),(3,'Water is made of ___ and ___.','Multi-blank · Science'),(4,'Arrange the plant life cycle.','Ordering · Science')])+'<div class="subtools"><span>Advanced search</span><span>Import questions ↗</span></div>'),
('B · Tap to expand',header+tools+'<div class="section-label">ALL QUESTIONS</div><div class="expand"><div class="expand-head"><span>What is the capital of Japan?</span><b>−</b></div><div class="expanded"><small>MULTIPLE CHOICE · GEOGRAPHY</small><p>Answer: Tokyo</p><button>Edit question ↗</button></div></div><div class="expand"><div class="expand-head"><span>Match each country to its capital.</span><b>＋</b></div></div><div class="expand"><div class="expand-head"><span>Water is made of ___ and ___.</span><b>＋</b></div></div><div class="expand"><div class="expand-head"><span>Arrange the plant life cycle.</span><b>＋</b></div></div><div class="subtools"><span>Advanced search</span><span>Import ↗</span></div>'),
('C · Question deck',header+tools+'<div class="section-label">BROWSE YOUR LIBRARY</div><div class="deck"><div class="paper"><div class="deck-label"><span>Multiple choice</span><span>⋯</span></div><h2>What is the capital of Japan?</h2><div class="answer">Geography &nbsp; / &nbsp; Capitals</div></div></div><div class="deck-controls"><button>‹</button><span>1 / 17 &nbsp; · &nbsp; Swipe to browse</span><button>›</button></div><div class="deck-actions"><button class="primary">Edit question</button><button>Show answer</button></div><div class="subtools"><span>Switch to list ☷</span><span>Import ↗</span></div>'),
('D · Subject directory',header+tools+'<div class="section-label">BROWSE BY SUBJECT</div><div>'+''.join(f'<div class="shelf"><span class="book">{icon}</span><div><b>{name}</b><small>{count} questions &nbsp; · &nbsp; {topics}</small></div><span>›</span></div>' for icon,name,count,topics in [('▤','Geography',8,'2 topics'),('⚗','Science',7,'3 topics'),('Aa','Unsorted',2,'No subject')])+'</div><div class="directory-detail"><b>LAST EDITED</b><p>Water is made of ___ and ___.</p><small>Multi-blank · Science &nbsp; ↗</small></div><button class="import-wide">View all 17 questions →</button><div class="subtools"><span>Advanced search</span><span>Import ↗</span></div>')
]
for i in range(2):
    cards=''.join(f'<section class="concept"><h2>{name}</h2><div class="phone">{brand}{content}{nav}</div></section>' for name,content in contents[i*2:i*2+2])
    out=f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Questions · new directions</title><style>{css}</style></head><body><main><div class="brand">RECALLFLOW · ROUND TWO</div><h1>Different directions for Questions</h1><p>Mobile concepts · sample content · no changes to your question bank.</p><div class="gallery">{cards}</div><a class="local-link" href="question-bank-round-two-{2 if i==0 else 1}.html">See the other two designs →</a></main></body></html>'
    (root/f'question-bank-round-two-{i+1}.html').write_text(out,encoding='utf-8')
